/* Editorial CMS. Plain structured blocks are escaped; stored HTML is never executed. */
if(window.OROO_CONFIG?.mode==='cloud')(()=>{
 const previousHome=home,previousRoute=flowRoute,previousRender=render;
 const categories=['Зөвлөгөө','Орон сууц','Түрээс','Зах зээл','Мэдээ','Амьдрал'];
 const state={cache:new Map(),draft:null,editorKey:null,busy:false,uploading:false,query:'',status:'',category:'',dirty:false};
 const uid=()=>crypto.randomUUID(),media=id=>id?{id,fullUrl:'/api/media/'+id+'/full',thumbUrl:'/api/media/'+id+'/thumb'}:null;
 const date=value=>{if(!value)return 'Ноорог';const parts=new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'Asia/Ulaanbaatar'}).formatToParts(new Date(value)),get=type=>parts.find(p=>p.type===type).value;return `${get('year')}.${get('month')}.${get('day')}`};
 const statusLabel=status=>({draft:'Ноорог',published:'Нийтэлсэн',archived:'Архив'}[status]||status);
 const errorText=error=>({article_incomplete:'Нийтлэхийн өмнө гарчиг, товч тайлбар, нүүр зураг болон үндсэн текстээ оруулна уу.',article_not_found:'Нийтлэл олдсонгүй эсвэл нийтэд нээлтгүй байна.',revision_conflict:'Энэ нийтлэл өөр цонхноос өөрчлөгдсөн. Таны бичсэн агуулга хадгалагдаж үлдсэн. Жагсаалтаас шинэ хувилбарыг нээж шалгана уу.',media_in_use:'Зургийг өөр зар эсвэл нийтлэлд ашигласан байна. Дахин байршуулна уу.',invalid_photo_ownership:'Өөрийн байршуулсан, өөр зар / нийтлэлд ашиглаагүй зураг сонгоно уу.'}[error.code]||cloudError(error));
 function get(path,{homeOnly=false}={}){
  let entry=state.cache.get(path);if(entry&&path.startsWith('/journal')&&Date.now()-entry.started>30000){state.cache.delete(path);entry=null}if(!entry){entry={loading:true,started:Date.now()};state.cache.set(path,entry);const at=location.hash;cloudAPI(path).then(data=>{entry.loading=false;entry.data=data;if(homeOnly){const host=document.getElementById('oroo-journal-home');if(host)host.innerHTML=homeContent(entry)}else if(location.hash===at)render()}).catch(error=>{entry.loading=false;entry.error=error;if(homeOnly){const host=document.getElementById('oroo-journal-home');if(host)host.innerHTML=homeContent(entry)}else if(location.hash===at)render()})}return entry;
 }
 function loading(entry){return entry.error?`<div class="journal-empty" role="alert"><h2>${esc(errorText(entry.error))}</h2><button onclick="orooJournal.refresh()">Дахин оролдох</button></div>`:'<div class="journal-loading" role="status">Нийтлэл ачаалж байна…</div>'}
 function shell(title,content,{admin=false,editor=false}={}){
  const menu=admin?[['overview','Ерөнхий самбар'],['listings','Зарын хяналт'],['brokers','Зуучлагчид'],['users','Хэрэглэгчид'],['reports','Мэдээлсэн зарууд'],['support','Тусламж'],['posts','Хөршүүдийн түүх'],['notices','Мэдээ'],['journal','Өрөө JOURNAL'],['campaigns','Зар сурталчилгаа'],['audit','Үйлдлийн түүх']].map(([key,label])=>`<a class="${key==='journal'?'active':''}" href="#/admin/${key}">${esc(label)}</a>`).join(''):'';
  let html=cloudPage(title,content,menu).replace('onclick="cloudInvalidate();render()"','onclick="orooJournal.refresh()"');if(editor)html=html.replace(/<button onclick="orooJournal.refresh\(\)">[\s\S]*?<\/button>/,'<a class="button-link" href="#/admin/journal">Жагсаалт руу</a>');return html;
 }
 function card(item){return `<a class="journal-card" href="#/journal/${item.id}"><div class="journal-card-image">${item.cover?`<img loading="lazy" src="${item.cover.thumbUrl}" alt="${esc(item.title)}">`:'<span>ӨРӨӨ JOURNAL</span>'}</div><div class="journal-card-copy"><div class="journal-meta"><span>${esc(item.category)}</span><time datetime="${esc(item.publishedAt||'')}">${esc(date(item.publishedAt))}</time></div><h3>${esc(item.title)}</h3><p>${esc(item.excerpt)}</p><span class="journal-read">Дэлгэрэнгүй унших ${icon('arrow-right')}</span></div></a>`}
 function homeContent(entry){return `<div class="section-head"><div><div class="eyebrow">ӨРӨӨ JOURNAL</div><h2>Танд зориулсан мэдээлэл</h2></div><a href="#/journal">Бүх нийтлэл ${icon('arrow-right')}</a></div>${entry.data?entry.data.items.length?`<div class="journal-grid">${entry.data.items.map(card).join('')}</div>`:'<div class="journal-home-empty"><b>Шинэ нийтлэлүүд удахгүй</b><p>Орон зай, түрээс болон өдөр тутмын амьдралын талаарх редакцын нийтлэлүүд энд гарна.</p></div>':loading(entry)}`}
 home=function(){const html=previousHome(),entry=get('/journal?home=1&limit=3',{homeOnly:true});return html.replace(/<section class="wrap"><div class="section-head"><h2>Танд зориулсан мэдээлэл<\/h2>[\s\S]*?<\/section>/,`<section class="wrap journal-home" id="oroo-journal-home">${homeContent(entry)}</section>`)};
 function listPath(admin=false){const p=new URLSearchParams({limit:admin?'15':'9'});if(state.query)p.set('q',state.query);if(admin&&state.status)p.set('status',state.status);if(!admin&&state.category)p.set('category',state.category);return (admin?'/admin/journal':'/journal')+'?'+p}
 function listPage(admin=false){const path=listPath(admin),entry=get(path);const intro=admin?`<section class="journal-admin-intro"><div><span class="eyebrow">ӨРӨӨ JOURNAL · РЕДАКЦ</span><h2>Уншигчдад хүргэх дараагийн түүх</h2><p>Нийтлэлээ бэлтгэж, урьдчилан хараад нийтлээрэй. Нийтэлсэн, нүүр хуудсанд харуулах сонголттой нийтлэлүүд үндсэн сайтад гарна.</p></div><a class="button-link primary" href="#/admin/journal/new">${icon('plus')} Нийтлэл бичих</a></section>`:'<div class="journal-list-intro"><span class="eyebrow">ӨРӨӨ JOURNAL</span><h2>Орон зайгаа илүү сайн таньж мэдээрэй.</h2><p>Орон сууц, түрээс, амьдралын хэв маяг болон Өрөө платформын шинэ мэдээлэл.</p></div>';
  const toolbar=`<form class="journal-toolbar" onsubmit="orooJournal.filter(event,${admin})"><label class="journal-search">${icon('search')}<input name="q" aria-label="Нийтлэл хайх" placeholder="Гарчиг, товч тайлбараар хайх" value="${esc(state.query)}" maxlength="100"></label><select name="${admin?'status':'category'}" aria-label="${admin?'Нийтлэлийн төлөв':'Ангилал'}"><option value="">${admin?'Бүх төлөв':'Бүх ангилал'}</option>${(admin?['draft','published','archived']:categories).map(value=>`<option value="${esc(value)}" ${(admin?state.status:state.category)===value?'selected':''}>${esc(admin?statusLabel(value):value)}</option>`).join('')}</select><button type="submit">Хайх</button></form>`;
  let content;if(!entry.data)content=loading(entry);else if(!entry.data.items.length)content=`<div class="journal-empty">${icon('file-text')}<h2>${admin?'Нийтлэл байхгүй':'Нийтлэл хараахан нийтлэгдээгүй байна'}</h2><p>${admin?'Эхний нийтлэлээ бичиж, ноорог хадгалах эсвэл нийтлэх боломжтой.':'Шинэ нийтлэл нэмэгдэхэд энд харагдана.'}</p>${admin?'<a class="button-link primary" href="#/admin/journal/new">+ Нийтлэл бичих</a>':''}</div>`;
  else content=admin?`<div class="journal-admin-list">${entry.data.items.map(item=>`<article><div class="journal-admin-cover">${item.cover?`<img loading="lazy" src="${item.cover.thumbUrl}" alt="">`:icon('file-text')}</div><div class="journal-admin-copy"><div class="journal-meta"><span class="journal-status ${item.status}">${statusLabel(item.status)}</span><span>${esc(item.category)}</span>${item.featured?'<span>Нүүр хуудас</span>':''}</div><h3><a href="#/admin/journal/${item.id}">${esc(item.title||'Гарчиггүй ноорог')}</a></h3><p>${esc(item.excerpt||'Товч тайлбар оруулаагүй')}</p><small>Шинэчилсэн: ${esc(date(item.updatedAt))} · ${esc(item.author)}</small></div><div class="journal-row-actions"><a class="button-link" href="#/admin/journal/${item.id}">Засах</a><button onclick="orooJournal.savedPreview('${item.id}')">Урьдчилан харах</button>${item.status!=='archived'?`<button onclick="orooJournal.archive('${item.id}',${item.revision})">Архивлах</button>`:''}${item.status==='published'?`<a href="#/journal/${item.id}">Сайт дээр харах ${icon('external-link')}</a>`:''}</div></article>`).join('')}</div>`:`<div class="journal-grid">${entry.data.items.map(card).join('')}</div>`;
  return shell(admin?'Өрөө JOURNAL':'Өрөө JOURNAL',intro+toolbar+content+(entry.data?.cursor?`<div class="journal-pagination"><button onclick="orooJournal.more(${admin})">Илүү олон нийтлэл</button></div>`:''),{admin});
 }
 function reader(item,{preview=false}={}){const pictures=item.cover||media(item.coverId),blocks=item.blocks||[],minutes=item.readingMinutes||Math.max(1,Math.ceil(blocks.map(b=>b.text||'').join(' ').split(/\s+/).filter(Boolean).length/200));return `<article class="journal-article">${preview?'<div class="journal-preview-label">УРЬДЧИЛСАН ХАРАГДАЦ · Одоогоор нийтлэхгүй</div>':'<nav class="journal-breadcrumb"><a href="#/">Нүүр</a><span>/</span><a href="#/journal">Өрөө JOURNAL</a></nav>'}<header class="journal-article-head"><span class="journal-category">${esc(item.category)}</span><h1>${esc(item.title||'Гарчиггүй нийтлэл')}</h1><p class="journal-deck">${esc(item.excerpt||'')}</p><div class="journal-byline"><span>${icon('file-text')}${esc(item.author||'Өрөө редакц')}</span><time datetime="${esc(item.publishedAt||'')}">${esc(date(item.publishedAt))}</time><span>${minutes} минут унших</span></div></header>${pictures?`<figure class="journal-cover"><img src="${pictures.fullUrl}" alt="${esc(item.coverAlt||item.title||'Нийтлэлийн нүүр зураг')}">${item.coverCaption?`<figcaption>${esc(item.coverCaption)}</figcaption>`:''}</figure>`:''}<div class="journal-article-body">${blocks.map(block=>block.type==='h2'?`<h2>${esc(block.text)}</h2>`:block.type==='quote'?`<blockquote>${esc(block.text)}</blockquote>`:block.type==='image'?`<figure><img loading="lazy" src="${(block.image||media(block.mediaId)).fullUrl}" alt="${esc(block.alt||'Нийтлэлийн зураг')}">${block.caption?`<figcaption>${esc(block.caption)}</figcaption>`:''}</figure>`:`<p>${esc(block.text)}</p>`).join('')}${item.sourceUrl&&validListingLink(item.sourceUrl)?`<aside class="journal-source">Эх сурвалж: <a href="${esc(item.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(item.sourceName||item.sourceUrl)} ${icon('external-link')}</a></aside>`:''}</div>${preview?'':`<footer class="journal-article-footer"><img src="assets/oroo.png" alt="Өрөө"><div><b>Өрөө JOURNAL</b><p>Таны орон зайг илүү ойлгомжтой болгох мэдээлэл.</p></div><a href="#/journal">Бусад нийтлэл ${icon('arrow-right')}</a></footer>`}</article>`}
 function articlePage(id){const entry=get('/journal/'+id);return `<div class="journal-reader-wrap">${entry.data?reader(entry.data.item):loading(entry)}${entry.error?'<p class="journal-return"><a href="#/journal">Бүх нийтлэл рүү буцах</a></p>':''}</div>`}
 function blank(){return {requestKey:uid(),title:'',excerpt:'',author:'Өрөө редакц',category:categories[0],featured:true,status:'draft',coverId:null,coverAlt:'',coverCaption:'',sourceName:'',sourceUrl:'',blocks:[{type:'p',text:'',key:uid()}]}}
 function hydrate(item){return {...item,blocks:item.blocks.map(b=>({...b,key:uid()}))}}
 function input(label,name,value,extra=''){return `<label class="journal-field">${label}<input name="${name}" value="${esc(value||'')}" ${extra}></label>`}
 function blockMarkup(block,index){return `<section class="journal-block" data-block="${block.key}"><div class="journal-block-heading"><b>${index+1}. ${{p:'Үндсэн текст',h2:'Дэд гарчиг',quote:'Онцлох эшлэл',image:'Зураг'}[block.type]}</b><div><button type="button" aria-label="Блок ${index+1} дээш" onclick="orooJournal.moveBlock('${block.key}',-1)" ${index===0?'disabled':''}>${icon('chevron-up')}</button><button type="button" aria-label="Блок ${index+1} доош" onclick="orooJournal.moveBlock('${block.key}',1)" ${index===state.draft.blocks.length-1?'disabled':''}>${icon('chevron-down')}</button><button type="button" aria-label="Блок ${index+1} хасах" onclick="orooJournal.removeBlock('${block.key}')">${icon('close')}</button></div></div>${block.type==='image'?`${block.mediaId?`<img class="journal-block-photo" src="${media(block.mediaId).thumbUrl}" alt="">`:''}<label class="journal-upload">${icon('image')} ${block.mediaId?'Өөр зураг сонгох':'Зураг нэмэх'}<input type="file" accept="image/jpeg,image/png" aria-label="Блок ${index+1} зураг" onchange="orooJournal.upload(this,'${block.key}')"></label>${input('Зургийн тайлбар','caption_'+block.key,block.caption,'maxlength="300"')}${input('Зургийн утга (alt)','alt_'+block.key,block.alt,'maxlength="160"')}`:block.type==='h2'?`<input class="journal-block-title" name="text_${block.key}" value="${esc(block.text||'')}" maxlength="160" aria-label="Дэд гарчиг ${index+1}" placeholder="Энэ хэсгийн гарчиг">`:`<textarea name="text_${block.key}" maxlength="${block.type==='quote'?1500:3000}" aria-label="${block.type==='quote'?'Эшлэл':'Үндсэн текст'} ${index+1}" rows="${block.type==='quote'?3:6}" placeholder="${block.type==='quote'?'Онцолж харуулах эшлэлээ бичнэ үү.':'Нийтлэлийнхээ энэ хэсгийг бичнэ үү. Шинэ хэсэг нэмэхэд доорх товчийг ашиглана.'}">${esc(block.text||'')}</textarea>`}</section>`}
 function editorPage(id){
  const key=id||'new';if(state.editorKey!==key){state.draft=null;state.editorKey=key;state.dirty=false}
  if(!state.draft){if(id){const entry=get('/admin/journal/'+id);if(!entry.data)return shell('Нийтлэл засах',loading(entry),{admin:true,editor:true});state.draft=hydrate(entry.data.item)}else state.draft=blank()}
  const d=state.draft;return shell(id?'Нийтлэл засах':'Шинэ нийтлэл',`<form id="journal-editor" class="journal-editor" onsubmit="orooJournal.save(event)" oninput="orooJournal.capture()"><div class="journal-editor-main"><section class="journal-editor-section"><div class="journal-section-title"><span>01</span><div><h2>Нийтлэлийн үндсэн мэдээлэл</h2><p>Гарчиг болон товч тайлбар нь нүүр хуудасны карт дээр харагдана.</p></div></div>${input('Гарчиг','title',d.title,'maxlength="160" placeholder="Уншигчдын анхаарлыг татах гарчиг"')}<label class="journal-field">Товч тайлбар<textarea name="excerpt" maxlength="400" rows="3" placeholder="Нийтлэл юуг өгүүлэхийг 1–2 өгүүлбэрээр тайлбарлаарай.">${esc(d.excerpt||'')}</textarea></label><div class="journal-form-pair"><label class="journal-field">Ангилал<select name="category">${categories.map(c=>`<option ${d.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label>${input('Зохиогч / Редакц','author',d.author,'maxlength="80"')}</div></section><section class="journal-editor-section"><div class="journal-section-title"><span>02</span><div><h2>Нүүр зураг</h2><p>Нүүр хуудас, нийтлэлийн жагсаалт болон дэлгэрэнгүйд ашиглана.</p></div></div>${d.coverId?`<img class="journal-editor-cover" src="${media(d.coverId).fullUrl}" alt="Нийтлэлийн нүүр зураг">`:''}<div class="journal-cover-actions"><label class="journal-upload">${icon('image')} ${d.coverId?'Нүүр зураг солих':'Нүүр зураг нэмэх'}<input type="file" accept="image/jpeg,image/png" aria-label="Нүүр зураг нэмэх" onchange="orooJournal.upload(this,'cover')"></label>${d.coverId?'<button type="button" onclick="orooJournal.removeCover()">Зураг хасах</button>':''}</div><small>JPEG / PNG · Нэг файл 8 MB хүртэл · Серверт хэмжээг багасгаж байршуулна.</small>${input('Зургийн утга (alt)','coverAlt',d.coverAlt,'maxlength="160"')}${input('Нүүр зургийн тайлбар / Эх сурвалж','coverCaption',d.coverCaption,'maxlength="300"')}</section><section class="journal-editor-section"><div class="journal-section-title"><span>03</span><div><h2>Нийтлэлийн агуулга</h2><p>Текст, дэд гарчиг, эшлэл болон зураг нэмж дарааллыг өөрчилж болно.</p></div></div>${d.blocks.map(blockMarkup).join('')}<div class="journal-add-blocks">${[['p','file-text','Текст'],['h2','file-text','Дэд гарчиг'],['quote','message','Эшлэл'],['image','image','Зураг']].map(([type,ico,label])=>`<button type="button" onclick="orooJournal.addBlock('${type}')">${icon(ico)}${label}</button>`).join('')}</div></section><section class="journal-editor-section"><h2>Эх сурвалж (заавал биш)</h2>${input('Эх сурвалжийн нэр','sourceName',d.sourceName,'maxlength="120"')}${input('Эх сурвалжийн холбоос','sourceUrl',d.sourceUrl,'type="url" placeholder="https://" maxlength="500"')}</section></div><aside class="journal-publish-panel"><div><span class="eyebrow">НИЙТЛЭХ ТОХИРГОО</span><h2>Уншигчдад хүргэхэд бэлэн үү?</h2><span class="journal-status ${d.status}">${statusLabel(d.status)}</span><p>Ноорог болон архивласан нийтлэл хэрэглэгчийн сайтад харагдахгүй.</p><label class="journal-featured"><input name="featured" type="checkbox" ${d.featured?'checked':''}>Нүүр хуудсанд харуулах</label><p class="journal-publish-note">Энэ сонголттой, нийтэлсэн сүүлийн 3 нийтлэл нүүр хуудсанд гарна. Бусад нийтлэл JOURNAL жагсаалтад хадгалагдана.</p><button type="button" onclick="orooJournal.preview()">${icon('eye')}Урьдчилан харах</button><button type="submit" name="action" value="draft">${icon('bookmark')}${d.status==='published'?'Ноорог болгож нуух':'Ноорог хадгалах'}</button><button class="primary" type="submit" name="action" value="published">${icon('send')}${d.status==='published'?'Өөрчлөлт нийтлэх':'Нийтлэх'}</button><p id="journal-save-status" role="status">${d.id?'Серверт хадгалсан хувилбар · '+d.revision:'Шинэ нийтлэл · Серверт хараахан хадгалаагүй'}</p><p id="journal-editor-error" class="cloud-error" role="alert" hidden></p><p class="journal-publish-note">Хадгалах товчийг дарж серверт хадгална. ${d.status==='published'?'Ноорог болговол нийтлэл сайтаас далдлагдана.':''}</p></div></aside></form>`,{admin:true,editor:true});
 }
 function capture(){const form=document.getElementById('journal-editor');if(!form||!state.draft)return;const f=new FormData(form),d=state.draft;for(const key of ['title','excerpt','category','author','coverAlt','coverCaption','sourceName','sourceUrl'])d[key]=String(f.get(key)||'');d.featured=f.has('featured');for(const block of d.blocks)if(block.type==='image'){block.alt=String(f.get('alt_'+block.key)||'');block.caption=String(f.get('caption_'+block.key)||'')}else block.text=String(f.get('text_'+block.key)||'');state.dirty=true;const label=document.getElementById('journal-save-status');if(label&&!state.busy&&!state.uploading)label.textContent='Хадгалаагүй өөрчлөлт байна'}
 function setBusy(busy){state.busy=busy;document.querySelectorAll('#journal-editor button,#journal-editor input,#journal-editor textarea,#journal-editor select').forEach(el=>{if(busy||state.uploading){if(el.dataset.journalDisabled===undefined)el.dataset.journalDisabled=String(el.disabled);el.disabled=true}else if(el.dataset.journalDisabled!==undefined){el.disabled=el.dataset.journalDisabled==='true';delete el.dataset.journalDisabled}});document.getElementById('journal-editor')?.setAttribute('aria-busy',String(busy||state.uploading))}
 async function save(event){event.preventDefault();if(state.busy||state.uploading)return;capture();const d=state.draft,status=event.submitter?.value||'draft';setBusy(true);const label=document.getElementById('journal-save-status'),error=document.getElementById('journal-editor-error');if(error)error.hidden=true;if(label)label.textContent='Серверт хадгалж байна…';try{const result=await cloudAPI('/admin/journal'+(d.id?'/'+d.id:''),{method:d.id?'PUT':'POST',body:{...d,status}});state.draft=hydrate(result.item);state.editorKey=result.item.id;state.dirty=false;state.cache.clear();cloudInvalidate();if(location.hash!=='#/admin/journal/'+result.item.id)location.hash='/admin/journal/'+result.item.id;else render();toast(status==='published'?'Нийтлэл нийтлэгдлээ · Сайт дээр харагдана':'Ноорог серверт хадгалагдлаа')}catch(e){if(error){error.textContent=errorText(e);error.hidden=false}if(label)label.textContent='Хадгалж чадсангүй · Бичсэн агуулга хэвээр байна'}finally{setBusy(false)}}
 async function upload(input,target){if(state.busy||state.uploading)return;capture();const file=input.files?.[0];if(!file)return;if(!['image/jpeg','image/png'].includes(file.type)||file.size>8*1024*1024){toast('8 MB хүртэл JPEG / PNG зураг сонгоно уу.');input.value='';return}state.uploading=true;setBusy(false);const label=document.getElementById('journal-save-status');if(label)label.textContent='Зураг байршуулж байна…';try{const full=await cloudJPEG(file,1920,.82,2*1024*1024),thumb=await cloudJPEG(file,480,.75,200*1024),key=uid();let uploaded;for(let attempt=0;attempt<2;attempt++){try{uploaded=await cloudAPI('/uploads/start',{method:'POST',body:{requestKey:key}});for(const [variant,blob] of [['full',full],['thumb',thumb]])if(!uploaded[variant+'Ready'])await cloudAPI('/uploads/'+uploaded.item.id+'/'+variant,{method:'PUT',body:blob});break}catch(e){if(attempt||e.status&&e.status<500)throw e}}if(target==='cover')state.draft.coverId=uploaded.item.id;else{const block=state.draft.blocks.find(b=>b.key===target);if(block)block.mediaId=uploaded.item.id}state.dirty=true;render();toast('Зураг байршууллаа · Нийтлэлээ хадгалаарай')}catch(e){const error=document.getElementById('journal-editor-error');if(error){error.hidden=false;error.textContent=errorText(e)}if(label)label.textContent='Зураг байршуулж чадсангүй. Дахин сонгоно уу.'}finally{state.uploading=false;setBusy(false);input.value=''}}
 function preview(){capture();if(!state.draft)return;modal(reader(state.draft,{preview:true}));document.querySelector('#overlay .modal')?.classList.add('journal-preview-modal')}
 async function savedPreview(id){try{const result=await cloudAPI('/admin/journal/'+id);modal(reader(result.item,{preview:true}));document.querySelector('#overlay .modal')?.classList.add('journal-preview-modal')}catch(e){toast(errorText(e))}}
 async function archive(id,revision){try{await cloudAPI('/admin/journal/'+id+'/archive',{method:'POST',body:{revision}});state.cache.clear();cloudInvalidate();render();toast('Архивлалаа · Нийтлэл сайтад харагдахгүй')}catch(e){toast(errorText(e))}}
 async function more(admin){const path=listPath(admin),entry=state.cache.get(path);if(!entry?.data?.cursor||entry.moreBusy)return;entry.moreBusy=true;try{const result=await cloudAPI(path+'&cursor='+encodeURIComponent(entry.data.cursor));entry.data={...result,items:[...entry.data.items,...result.items]};render()}catch(e){toast(errorText(e))}finally{entry.moreBusy=false}}
 function refresh(){capture();state.cache.clear();render()}
 function adminPage(id){const session=get('/session');if(!session.data)return shell('Өрөө JOURNAL',loading(session),{admin:true});if(!session.data.user)return cloudGate();if(session.data.user.role!=='admin')return shell('Нэвтрэх эрхгүй','<p>Нийтлэл удирдах эрхийг зөвхөн платформын администратор ашиглана.</p>');return id?editorPage(id==='new'?null:id):listPage(true)}
 flowRoute=function(parts){if(parts[0]==='admin'&&parts[1]==='journal')return adminPage(parts[2]);if(parts[0]==='journal')return parts[1]?articlePage(parts[1]):listPage(false);return previousRoute(parts)};
 window.orooJournal={capture,save,upload,preview,savedPreview,archive,more,refresh,reader,card,
  filter(event,admin){event.preventDefault();const f=new FormData(event.target);state.query=String(f.get('q')||'').trim();if(admin)state.status=String(f.get('status')||'');else state.category=String(f.get('category')||'');state.cache.clear();render()},
  addBlock(type){if(state.busy||state.uploading)return;capture();if(state.draft.blocks.length>=60){toast('60 хүртэл хэсэг нэмнэ үү.');return}state.draft.blocks.push({type,text:'',key:uid()});render()},
  moveBlock(key,direction){if(state.busy||state.uploading)return;capture();const at=state.draft.blocks.findIndex(b=>b.key===key),to=at+direction;if(to<0||to>=state.draft.blocks.length)return;const [block]=state.draft.blocks.splice(at,1);state.draft.blocks.splice(to,0,block);render()},
  removeBlock(key){if(state.busy||state.uploading)return;capture();state.draft.blocks=state.draft.blocks.filter(b=>b.key!==key);render()},
  removeCover(){capture();state.draft.coverId=null;render()}
 };
 render=function(){previousRender();const parts=location.hash.slice(2).split('/');if(parts[0]==='journal')document.title=(state.cache.get('/journal/'+parts[1])?.data?.item?.title||'Өрөө JOURNAL')+' · Өрөө';if(parts[0]==='admin'&&parts[1]==='journal')document.title='Өрөө JOURNAL · Өрөө ADMIN'};
 if(document.documentElement.classList.contains?.('cloud-ready'))render();
 window.addEventListener('focus',()=>{if(!location.hash||location.hash==='#/'||location.hash==='#/journal'){state.cache.delete('/journal?home=1&limit=3');const host=document.getElementById('oroo-journal-home');if(host)host.innerHTML=homeContent(get('/journal?home=1&limit=3',{homeOnly:true}))}});
})();
